package com.aoo.bcg.common.invite;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class InviteAdmissionPolicyTest{@Test void checksEveryAccessDomainAfterSignatureVerification(){var policy=new InviteAdmissionPolicy();var allowed=new InviteAdmissionPolicy.Context(true,true,true,true,9,true,true,true,true,true,false,true);assertTrue(policy.decide(allowed).allowed());assertEquals("BLACKLISTED",policy.decide(change(allowed,0)).code());assertEquals("PRIVATE_ACCESS_REQUIRED",policy.decide(change(allowed,1)).code());assertEquals("CLUB_MEMBERSHIP_REQUIRED",policy.decide(change(allowed,2)).code());assertEquals("TOURNAMENT_INELIGIBLE",policy.decide(change(allowed,3)).code());assertEquals("SPECTATOR_NOT_ALLOWED",policy.decide(change(allowed,4)).code());}private static InviteAdmissionPolicy.Context change(InviteAdmissionPolicy.Context c,int kind){return new InviteAdmissionPolicy.Context(c.roomExists(),c.roomJoinable(),c.privateRoom(),kind!=1,c.requiredClubId(),kind!=2,c.tournamentRoom(),kind!=3,c.spectatorRequested(),kind!=4,kind==0,c.versionCompatible());}}
